# jellyqda stress test -----------------------------------------------------------
#
# How does jellyqda behave in large research projects? Three scenarios from
# common study practice (all transcripts FICTIONAL, generated by
# data-raw/transcript_generator.R):
#   S   15 interviews  -- e.g. a master's thesis
#   M   50 interviews  -- e.g. a PhD or a funded project
#   L  150 interviews  -- a large multi-site / panel study (upper end)
# Each interview 30-90 minutes (speaker turns with time stamps), a code
# system of 8 families x 4 subcodes (40 codes), about one coding per two to
# three participant turns -- every coding made with qda_code(), one by one,
# as in real work (so the audit trail grows realistically).
#
# Measures: import, coding (time per action), project size, every analysis,
# graphics, report, exports, backup, undo, intercoder, and the main outputs
# of the app (server side, via shiny::testServer).
#
# Run from the root of the source folder (takes a while for L):
#   Rscript -e 'pkgload::load_all("."); source("dev/stress_test.R")'
#   options(jellyqda.stress.sizes = c(15, 50))   # only some scenarios
# Results: printed, and written to dev/stress-test-results.csv.

suppressMessages(library(jellyqda))
source(file.path("data-raw", "transcript_generator.R"))   # make_transcript()

sizes <- getOption("jellyqda.stress.sizes", c(15, 50, 150))
root <- getOption("jellyqda.stress.dir", file.path(tempdir(), "jellyqda-stress"))
reps <- 3L                                                    # median of 3 runs

timeit <- function(expr, n = reps) {
  e <- substitute(expr); env <- parent.frame()
  t <- vapply(seq_len(n), function(i) {
    gc(FALSE); unname(system.time(eval(e, env))["elapsed"])
  }, numeric(1))
  stats::median(t)
}
results <- list()
note <- function(size, step, seconds, extra = "") {
  results[[length(results) + 1]] <<- data.frame(interviews = size, step = step,
                                                 seconds = round(seconds, 3), detail = extra)
  cat(sprintf("  %-38s %8.3f s  %s\n", step, seconds, extra))
}
mb <- function(f) sprintf("%.1f MB", sum(file.info(f)$size) / 1024^2)

families <- list(
  "Career path" = c("Small company", "Corporation", "Training", "Turning point"),
  "Motivation" = c("Meaning", "Customer contact", "Learning", "Freedom"),
  "Team climate" = c("Trust", "Conflict", "Onboarding", "Remote work"),
  "Workload" = c("Overtime", "Meetings", "Boundaries", "Recovery"),
  "Leadership" = c("Support", "Decisions", "Feedback", "Distance"),
  "Pay" = c("Salary", "Security", "Benefits", "Comparison"),
  "Future" = c("Staying", "Own business", "Growth", "Change"),
  "Context" = c("Covid", "Market", "Technology", "Family"))
palette <- c("#0072B2", "#E69F00", "#009E73", "#D55E00", "#56B4E9", "#CC79A7", "#999999", "#F0E442")

for (n in sizes) {
  cat(sprintf("\n=== %d interviews ===\n", n))
  dir <- file.path(root, sprintf("n%03d", n)); unlink(dir, recursive = TRUE)
  dir.create(file.path(dir, "transcripts"), recursive = TRUE)
  set.seed(n)
  minutes <- sample(30:90, n, replace = TRUE)
  files <- vapply(seq_len(n), function(i) {
    f <- file.path(dir, "transcripts", sprintf("interview_%03d.txt", i))
    writeLines(make_transcript(minutes[i], sprintf("DEMO_STRESS_%03d", i), sprintf("P%03d", i),
                               "participant", 1000 + i), f, useBytes = TRUE)
    f
  }, character(1))
  note(n, "transcripts (generated)", 0, sprintf("%d min of talk, %s", sum(minutes), mb(files)))

  proj <- file.path(dir, "stress.jellyqda")
  qda_open(proj, auto_snapshot = Inf)    # automatic backups measured separately below
  note(n, "import (speaker turns)", system.time(qda_import(files, segments = "speaker"))[["elapsed"]],
       sprintf("%d segments", sum(qda_sources()$segments)))

  for (k in seq_along(families)) {
    qda_code_add(names(families)[k], color = palette[k])
    for (s in families[[k]]) qda_code_add(s, parent = names(families)[k])
  }
  codes <- qda_codes()
  # codings: about every 2nd-3rd participant turn, some only part of the
  # turn, some turns with two codes (overlaps)
  plan <- do.call(rbind, lapply(qda_sources()$id, function(sid) {
    sg <- qda_source_segments(sid)
    p <- sg[grepl("\\] P: ", sg$text), ]
    p <- p[sort(sample(nrow(p), ceiling(nrow(p) * 0.4))), ]
    if (nrow(p) == 0) return(NULL)
    rows <- data.frame(sid = sid, start = p$start, end = p$end,
                       code = sample(codes$id, nrow(p), replace = TRUE))
    part <- runif(nrow(rows)) < 0.3
    rows$end[part] <- pmin(rows$end[part], rows$start[part] + 120L)
    two <- rows[runif(nrow(rows)) < 0.2, , drop = FALSE]
    two$code <- sample(codes$id, nrow(two), replace = TRUE)
    rbind(rows, two)
  }))
  t_code <- system.time(for (i in seq_len(nrow(plan)))
    qda_code(plan$sid[i], plan$code[i], start = plan$start[i], end = plan$end[i]))[["elapsed"]]
  note(n, "coding with qda_code() (all)", t_code, sprintf("%d codings, %.1f ms each", nrow(plan), 1000 * t_code / nrow(plan)))
  note(n, "project file", 0, mb(proj))

  # latency of one action in the full project
  sg1 <- qda_source_segments(1)
  note(n, "one more coding (+ undo)", timeit({ qda_code(1, codes$id[2], start = sg1$start[3], end = sg1$end[3]); qda_undo() }))
  note(n, "qda_history() (undo stack)", timeit(qda_history()))

  note(n, "qda_sources()", timeit(qda_sources()))
  note(n, "qda_codes()", timeit(qda_codes()))
  note(n, "qda_codings()", timeit(qda_codings()))
  note(n, "qda_stats()", timeit(qda_stats()))
  note(n, "qda_matrix()", timeit(qda_matrix()))
  note(n, "qda_words(n = 50)", timeit(qda_words(n = 50)))
  note(n, "qda_kwic('customer')", timeit(qda_kwic("customer")))
  note(n, "qda_cooccurrence()", timeit(qda_cooccurrence()))
  note(n, "qda_portrait()", timeit(qda_portrait()))
  cooc <- qda_cooccurrence()
  note(n, "heatmap + network (SVG)", timeit({ qda_plot_cooccurrence(cooc); qda_plot_network(cooc) }))
  note(n, "portraits (SVG)", timeit(qda_plot_portrait()))
  rep_html <- NULL
  note(n, "report (HTML)", timeit(rep_html <- jellyqda:::.report_html(), n = 1),
       sprintf("%.1f MB", nchar(rep_html, type = "bytes") / 1024^2))
  note(n, "qda_export('all')", timeit(qda_export("all"), n = 1))
  qd <- NULL
  note(n, "qda_export_qdpx()", timeit(qd <- qda_export_qdpx(), n = 1), mb(qd))
  bk <- NULL
  note(n, "qda_backup() (as every 25 actions)", timeit(bk <- qda_backup(quiet = TRUE), n = 1), mb(bk))
  b <- file.path(dir, "coder_b.jellyqda")
  note(n, "qda_intercoder_copy()", timeit(qda_intercoder_copy(b, overwrite = TRUE), n = 1))
  note(n, "qda_intercoder() (vs. empty copy)", timeit(qda_intercoder(b, log = FALSE)))

  # App, server side. Outputs are computed when the page is first shown (all
  # panels in one go) and then only when something changes; so we measure
  # (1) the first page build, (2) opening a document, (3) the graphics window
  # -- each as the time of the update that triggers it.
  big <- qda_sources()$id[which.max(qda_sources()$chars)]
  shiny::testServer(jellyqda:::.jellyqda_server, {
    note(n, "app: first page (all panels)", timeit(htmltools::renderTags(output$doc_tree), n = 1))
    note(n, "app: open the longest document", timeit({ session$setInputs(open_source = big)
                                                       htmltools::renderTags(output$doc) }, n = 1),
         sprintf("%d characters", max(qda_sources()$chars)))
    note(n, "app: graphics window (3 graphics)", timeit({
      session$setInputs(viz_unit = "segment", viz_level = "code", viz_measure = "n", viz_min_n = 1, viz_layout = "circle")
      htmltools::renderTags(output$viz_cooc); htmltools::renderTags(output$viz_net); htmltools::renderTags(output$viz_portrait)
    }, n = 1))
    note(n, "app: one coding (mark + click code)", timeit({
      session$setInputs(selection = list(start = 10L, end = 60L, text = "x"))
      session$setInputs(assign_code = qda_codes()$id[2])
    }, n = 1))
  })
  qda_close()
}

res <- do.call(rbind, results)
utils::write.csv(res, file.path("dev", "stress-test-results.csv"), row.names = FALSE)
cat("\nResults written to dev/stress-test-results.csv\n")
